configuration:

    ozone.metadata.dirs
    {{ ozone_metadata_dir }}


    ozone.scm.datanode.id.dir
    {{ ozone_data_dir }}


    hdds.datanode.dir
    {{ hdds_data_dir }}


    hdds.scmclient.max.retry.timeout
    30s


    ozone.scm.primordial.node.id
    {{ hostvars[groups['scms'][0]]['scmid'] }}


    hdds.container.report.interval
    60s


    ozone.om.s3.grpc.server_enabled
    true


    ozone.recon.db.dir
    {{ ozone_metadata_dir }}/recon


    ozone.recon.address
    {{ groups['recon'][0] }}


    dfs.container.ratis.datastream.enabled
    true


    ozone.server.default.replication
    3


    hdds.scm.safemode.min.datanode
    1




    ozone.om.ratis.enable
    true


    ozone.om.service.ids
    {{ ozone_name }}-om


    ozone.om.nodes.{{ozone_name}}-om
    {{ groups['oms'] | map('extract', hostvars) | map(attribute='omid') | join(',') }}

{%- for host in groups['oms'] -%}

    ozone.om.address.{{ozone_name}}-om.{{hostvars[host]['omid']}}
    {{host}}

{%- endfor -%}


    ozone.scm.ratis.enable
    true


    ozone.scm.service.ids
    {{ ozone_name }}-scm


    ozone.scm.nodes.{{ozone_name}}-scm
    {{ groups['scms'] | map('extract', hostvars) | map(attribute='scmid') | join(',') }}


{%- for host in groups['scms'] -%}

    ozone.scm.address.{{ozone_name}}-scm.{{hostvars[host]['scmid']}}
    {{host}}

{%- endfor -%}
